pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(address actor, uint256 limit) public {
        vm.assume(actor != address(0) && actor != address(c));
        // owner opens the contract to the public
        vm.prank(address(this));
        c.OpenToThePublic();
        // owner sets a fuzzed bet limit so wager is admissible
        vm.prank(address(this));
        c.AdjustBetAmounts(limit);
        vm.deal(actor, limit);
        bool ok;
        vm.prank(actor);
        try c.wager{value: limit}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

