pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address __invmut_eoa;

    function setUp() public {
        __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
        vm.prank(__invmut_eoa);
        c.OpenToThePublic();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // The contract is open (owner opened it in setUp), betLimit is 0,
        // so any real person (msg.sender == tx.origin) can wager 0 ether
        // and must be registered as a player.
        vm.startPrank(actor, actor);
        c.wager{value: 0}();
        vm.stopPrank();
        assertTrue(c.hasPlayerWagered(actor));
    }
}

