pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint256).max / 2);
        vm.prank(__invmut_eoa);
        c.AdjustBetAmounts(amount);
        assertTrue(c.currentBetLimit() == amount);
    }
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(uint256 a) public {
		require(a != c.currentBetLimit());
		c.AdjustBetAmounts(a);
		assert(c.currentBetLimit() == a);
	}
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(uint256 amount1, uint256 amount2) public {
		require(c.owner() == address(this));
		require(amount1 != amount2);
		c.AdjustDifficulty(amount1);
		c.AdjustDifficulty(amount2);
		assert(c.currentDifficulty() == amount2);
	}
	receive() external payable {}
	fallback() external payable {}
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(uint256 d) public {
		// This contract is not the owner of c (owner is the external deployer).
		// In P this call reverts; in M it succeeds and sets difficulty to d.
		c.AdjustDifficulty(d);
		assert(c.currentDifficulty() != d);
	}
	receive() external payable {}
	fallback() external payable {}
}
